template:
discovery.azure "${1:default}" {
  managed_identity {
    client_id = "${2}"
  }
  oauth {
    client_id = "${2}"
    client_secret = "${3}"
    tenant_id = "${4}"
  }
  tls_config {
    $0
  }

  // Exported fields:
  // - targets (list(map(string))): The set of targets discovered from the Azure API.
}
